package web

//go:generate go tool templ generate

// The page's scripts are TypeScript in ts/, bundled into static/app.js and static/theme.js (committed, like the
// generated templates). theme.js is loaded first, without defer, so the saved theme is applied before the
// first paint. esbuild is a pinned Go tool in go.mod, so this needs no Node. Types are checked separately,
// in CI, by tools/typecheck.
//go:generate go tool esbuild ts/app.ts --bundle --minify --format=iife --target=es2020 --legal-comments=none --sourcemap=linked "--banner:js=/* Generated by esbuild from internal/web/ts. Do not edit; run go generate ./... */" --outfile=static/app.js
//go:generate go tool esbuild ts/theme.ts --bundle --minify --format=iife --target=es2020 --legal-comments=none --sourcemap=linked "--banner:js=/* Generated by esbuild from internal/web/ts. Do not edit; run go generate ./... */" --outfile=static/theme.js
// immich-button.js is not part of the page: a reverse proxy loads it into Immich's own pages (docs/find-handoff.md).
//go:generate go tool esbuild ts/immich-button.ts --bundle --minify --format=iife --target=es2020 --legal-comments=none "--banner:js=/* Generated by esbuild from internal/web/ts. Do not edit; run go generate ./... */" --outfile=static/immich-button.js
